def _f(lc, lp, pb, nl=273):
    return [{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME, "lc": lc, "lp": lp, "pb": pb, "nice_len": nl, "mf": lzma.MF_BT4, "depth": 0}]

_FILTERS = [_f(3,0,0), _f(4,0,0), _f(2,0,0), _f(1,0,0), _f(0,0,0), _f(3,0,2), _f(4,0,1)]


def compress(data: bytes) -> bytes:
    best = b'\xff' + data
    for i, fl in enumerate(_FILTERS):
        out = lzma.compress(data, format=lzma.FORMAT_RAW, filters=fl)
        if len(out) + 1 < len(best):
            best = bytes([i]) + out
    out = bz2.compress(data, 9)
    if len(out) + 1 < len(best):
        best = b'\xfe' + out
    return best


def decompress(data: bytes) -> bytes:
    if not data:
        return b''
    t = data[0]
    if t == 0xff:
        return data[1:]
    if t == 0xfe:
        return bz2.decompress(data[1:])
    return lzma.decompress(data[1:], format=lzma.FORMAT_RAW, filters=_FILTERS[t])

